"""Print the Alder Carr Pottery studio statement.

Walks the firing room logs in firings/ and prints one line per client,
followed by a totals line.
"""
import csv
import os

LOGS = os.path.join(os.path.dirname(os.path.abspath(__file__)), "firings")


def pounds(pence):
    return "%d.%02d" % (pence // 100, pence % 100)


def log_rows():
    rows = []
    for name in sorted(os.listdir(LOGS)):
        if name.endswith(".csv"):
            with open(os.path.join(LOGS, name), newline="") as handle:
                rows.extend(csv.DictReader(handle))
    return rows


def main():
    loads = {}
    amounts = {}
    for row in log_rows():
        # a cancelled load is never charged
        if row["status"] == "voided":
            continue
        client = row["client"]
        loads[client] = loads.get(client, 0) + 1
        amounts[client] = amounts.get(client, 0) + int(row["charge_pence"])
    for client in sorted(loads):
        print("%s,%d,%s" % (client, loads[client], pounds(amounts[client])))
    print("TOTAL,%d,%s" % (sum(loads.values()), pounds(sum(amounts.values()))))


main()
